import{c as a,Q as t,j as o,m as i}from"./chunks/framework.W-g_WCNV.js";const g=JSON.parse('{"title":"Changelog","description":"Version history for GateKeeper.","frontmatter":{"title":"Changelog","description":"Version history for GateKeeper."},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md"}'),n={name:"reference/changelog.md"};function r(s,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h2 id="v0-9-4" tabindex="-1">v0.9.4 <a class="header-anchor" href="#v0-9-4" aria-label="Permalink to &quot;v0.9.4&quot;">​</a></h2><h3 id="mobile-app-sign-in" tabindex="-1">Mobile app sign-in <a class="header-anchor" href="#mobile-app-sign-in" aria-label="Permalink to &quot;Mobile app sign-in&quot;">​</a></h3><ul><li><strong>Custom redirect schemes are accepted</strong> - An application that is not a website, such as the Immich phone app, receives its authorization code on an address like <code>app.immich:///oauth-callback</code>. GateKeeper refused those, so mobile sign-in could not complete. A client that registers such an address is now treated as a native application, which permits it. Clients using only <code>http</code> or <code>https</code> are unchanged, and the address is still matched exactly against the registered list.</li><li><strong>Plain HTTP still works alongside it</strong> - Native clients are normally held to stricter transport rules, which would have broken web sign-in for anyone reaching their app over plain HTTP on a local network. Those clients keep working.</li><li><strong><a href="/integrations/immich.html">Immich guide</a></strong> - A full walkthrough covering the web interface and the mobile app.</li></ul><h3 id="client-test-dialog" tabindex="-1">Client test dialog <a class="header-anchor" href="#client-test-dialog" aria-label="Permalink to &quot;Client test dialog&quot;">​</a></h3><ul><li><strong>The sign-in link works</strong> - It pointed at <code>/oauth/authorize</code>, which is not a route this server serves, so opening the auth flow always returned 404. It now uses <code>/authorize</code>, and the redirect address is encoded so one containing a query string is no longer mangled.</li><li><strong>The access policy is reported correctly</strong> - The dialog read the policy from a table that does not exist, so the query silently failed and every client was described as open to all users even when a policy was attached.</li><li><strong>Passing checks are visible</strong> - The tick used a colour that is not defined in the stylesheet, so successful checks rendered as blank rows.</li><li><strong>More detail</strong> - The dialog now lists the client&#39;s redirect URIs and reports whether it counts as a web or native application.</li></ul><h3 id="oidc-signing-key-rotation" tabindex="-1">OIDC signing key rotation <a class="header-anchor" href="#oidc-signing-key-rotation" aria-label="Permalink to &quot;OIDC signing key rotation&quot;">​</a></h3><p>The documentation has always said the OIDC signing key rotates every 30 days. It did not. The key was generated on first run and then kept forever, because nothing ever triggered a rotation.</p><ul><li><strong>Rotation now happens</strong> - GateKeeper checks hourly and replaces the signing key once it is 30 days old. No restart needed.</li><li><strong>Old tokens keep working</strong> - The retired key stays published in the JWKS for another 48 hours, far longer than the 15 minute lifetime of the tokens it signed. After that it is deleted.</li><li><strong>Visible on the dashboard</strong> - System health now shows when the current key was last rotated and the date it is next due, instead of only claiming that rotation happens.</li></ul><hr><h2 id="v0-9-3" tabindex="-1">v0.9.3 <a class="header-anchor" href="#v0-9-3" aria-label="Permalink to &quot;v0.9.3&quot;">​</a></h2><p>Fixes an OIDC regression introduced in v0.9.2 and moves cross-domain ForwardAuth configuration into the admin UI. Upgrade from v0.9.2 is recommended.</p><h3 id="bug-fixes" tabindex="-1">Bug fixes <a class="header-anchor" href="#bug-fixes" aria-label="Permalink to &quot;Bug fixes&quot;">​</a></h3><ul><li><strong>OIDC sign-in works again (regression in v0.9.2)</strong> - The <code>/userinfo</code> response stopped including the <code>email</code> claim, so apps could not identify the user and returned them to their own login page, appearing as though nothing happened. v0.9.2 limited claims to a token&#39;s recorded scopes, but tokens do not always have their scopes recorded, and those tokens then received no claims at all. Claims are now limited only when the granted scopes are actually known. Anyone running v0.9.2 with OIDC applications should upgrade.</li><li><strong>TOTP recovery codes no longer hang</strong> - Redeeming a recovery code wrote to the database while a query cursor was still open. GateKeeper uses a single database connection, so the write waited on a connection that could never be released and the request hung until it timed out. This affected all previous versions.</li></ul><h3 id="protected-app-domains-moved-into-settings" tabindex="-1">Protected app domains moved into Settings <a class="header-anchor" href="#protected-app-domains-moved-into-settings" aria-label="Permalink to &quot;Protected app domains moved into Settings&quot;">​</a></h3><p>Cross-domain ForwardAuth apps need their domain on an allowlist before GateKeeper will return a user to them after signing in. This previously required the <code>REDIRECT_ALLOWED_HOSTS</code> environment variable and a restart.</p><ul><li><strong>Configurable in the admin UI</strong> - Set them under <strong>Settings - Access control - Protected app domains</strong>. Changes apply immediately, with no restart.</li><li><strong>One consistent entry format</strong> - Each entry covers the domain and all of its subdomains, so <code>example.net</code> allows <code>app.example.net</code>. Writing <code>.example.net</code>, <code>*.example.net</code>, or pasting a full URL all mean the same thing. Previously a domain written without a leading dot matched only that exact hostname, which silently failed to cover the app subdomains it was meant to allow.</li><li>The environment variable still works for automated deployments, and entries from both sources are combined.</li></ul><h3 id="tests-and-ci" tabindex="-1">Tests and CI <a class="header-anchor" href="#tests-and-ci" aria-label="Permalink to &quot;Tests and CI&quot;">​</a></h3><ul><li><strong>Tests run on every push and pull request</strong> - A GitHub Actions workflow builds, vets, checks formatting, and runs the suite with race detection and coverage.</li><li><strong>Coverage extended across the application</strong> - The suite now also covers password and OTP handling, TOTP enrollment, validation, lockout and recovery codes, backup encryption, configuration validation, database migrations and restore, CSRF, template parsing, and the OIDC claim and redirect rules. Two of the bugs fixed above were found by these tests.</li><li>Template tests guard against regressions that are otherwise invisible until a page breaks: page-scoped variables used inside a range block, inline scripts missing a CSP nonce, and inline event handlers that a nonce-based policy blocks.</li></ul><hr><h2 id="v0-9-2" tabindex="-1">v0.9.2 <a class="header-anchor" href="#v0-9-2" aria-label="Permalink to &quot;v0.9.2&quot;">​</a></h2><p>A security release. An independent audit of the codebase produced 14 findings, all of which are fixed here. Two of them change behaviour you will notice, so read the upgrade notes at the end.</p><h3 id="cross-domain-sign-in-hardened-critical" tabindex="-1">Cross-domain sign-in hardened (critical) <a class="header-anchor" href="#cross-domain-sign-in-hardened-critical" aria-label="Permalink to &quot;Cross-domain sign-in hardened (critical)&quot;">​</a></h3><ul><li><strong>Handoff tokens no longer carry a session</strong> - When signing in to an app on a different domain, GateKeeper previously put a signed copy of the session identifier in the redirect URL. Anyone who saw that URL, in a server log or browser history, could reuse the session. The handoff is now a random one-time token stored server-side. It can be redeemed exactly once, only by the host it was issued for, and it expires after two minutes. The receiving app gets a brand new session of its own.</li><li><strong>Redirect targets are checked against an allowlist</strong> - <code>redirect_uri</code> was previously followed wherever it pointed, so a crafted login link could send an authenticated user, and their handoff token, to an attacker&#39;s site. Relative paths are always allowed. Absolute URLs must match your <code>BASE_URL</code>, <code>ADMIN_URL</code>, <code>COOKIE_DOMAIN</code>, or the new <strong>Protected app domains</strong> list in Settings (also settable with <code>REDIRECT_ALLOWED_HOSTS</code>). Anything else falls back to the home page.</li><li><strong>Handoff tokens are kept out of logs</strong> - The ForwardAuth debug line now records only the request path, never the query string that carries the token.</li></ul><h3 id="qr-sign-in-hardened-high" tabindex="-1">QR sign-in hardened (high) <a class="header-anchor" href="#qr-sign-in-hardened-high" aria-label="Permalink to &quot;QR sign-in hardened (high)&quot;">​</a></h3><ul><li><strong>One code, one session</strong> - An approved QR code could previously be polled repeatedly, and each poll issued another session. A code is now claimed atomically and works exactly once.</li><li><strong>Bound to the browser that showed it</strong> - Claiming a code requires a cookie set on the device that displayed it, so an approval obtained by sending someone an approval link cannot be collected by the sender. The approval form is also CSRF protected.</li></ul><h3 id="admin-panel-and-account-security" tabindex="-1">Admin panel and account security <a class="header-anchor" href="#admin-panel-and-account-security" aria-label="Permalink to &quot;Admin panel and account security&quot;">​</a></h3><ul><li><strong>Command palette escapes user data (high)</strong> - A display name containing markup was inserted into the admin command palette without escaping, so any user could run script in an admin&#39;s browser and escalate privileges. All values are now escaped at the point of insertion.</li><li><strong>Content-Security-Policy no longer allows inline script</strong> - <code>script-src</code> uses a per-response nonce instead of <code>&#39;unsafe-inline&#39;</code>, so injected script is refused by the browser even if it ever reaches a page.</li><li><strong>Admin login is rate limited</strong> - Repeated failures from one address are now throttled before the expensive password hash runs, which closes both an online guessing path and a way to exhaust server memory.</li><li><strong>Trusted devices are opt-in</strong> - Passing two-factor authentication no longer silently marks the browser trusted for 30 days. There is now a &quot;Trust this device for 30 days&quot; checkbox, and a trust token only works in the browser it was issued to.</li></ul><h3 id="data-at-rest" tabindex="-1">Data at rest <a class="header-anchor" href="#data-at-rest" aria-label="Permalink to &quot;Data at rest&quot;">​</a></h3><ul><li><strong>Session and trusted-device tokens are hashed</strong> - The database stores only a hash, so a copy of the database no longer yields usable sign-in credentials.</li><li><strong>Third-party credentials are encrypted</strong> - SMTP passwords, S3 keys, social login secrets, and webhook tokens are encrypted with AES-256-GCM, matching how injected policy passwords were already handled.</li><li><strong>Retired TOTP secrets are re-enrolled</strong> - Secrets still stored in the pre-v0.4.0 format were recoverable from a database read. They are now cleared instead of reused, and the user is asked to set up their authenticator again.</li></ul><h3 id="outbound-requests-and-oidc" tabindex="-1">Outbound requests and OIDC <a class="header-anchor" href="#outbound-requests-and-oidc" aria-label="Permalink to &quot;Outbound requests and OIDC&quot;">​</a></h3><ul><li><strong>Requests to internal addresses are blocked</strong> - Client icon URLs and webhook endpoints could be pointed at loopback, private, or cloud metadata addresses. Both now resolve and check the destination on every connection and redirect.</li><li><strong>Icons are served as images only</strong> - Fetched icon data is sniffed and rejected unless it is really an image, so the public icon endpoint cannot return arbitrary fetched content.</li><li><strong><code>end_session</code> validates its redirect</strong> - <code>post_logout_redirect_uri</code> must now match a registered client redirect URI or a trusted host.</li><li><strong><code>email_verified</code> reflects reality</strong> - The claim previously always reported true. It now reports whether the user actually confirmed their address by completing an email code. Where the granted scopes are recorded on a token, <code>email</code> and <code>profile</code> claims are limited to those scopes; tokens without recorded scopes still receive the standard claims so existing integrations keep working.</li><li><strong>Client secrets compare in constant time.</strong></li></ul><h3 id="bug-fixes-1" tabindex="-1">Bug fixes <a class="header-anchor" href="#bug-fixes-1" aria-label="Permalink to &quot;Bug fixes&quot;">​</a></h3><ul><li><strong>TOTP recovery codes no longer hang</strong> - Redeeming a recovery code wrote to the database while a query cursor was still open. GateKeeper uses a single database connection, so the write waited on a connection that could never be released and the request hung until it timed out. Found by the new test suite.</li></ul><h3 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h3><ul><li>The repository now has a Go test suite covering these changes: single-use and host-bound handoff tokens, redirect allowlisting, QR single-use and browser binding (including a concurrent-claim race), token hashing, rate limiting, settings encryption, CSP nonce handling, and the internal-address blocklist. It also covers password and OTP handling, TOTP enrollment and recovery, backup encryption, configuration validation, migrations and restore, template parsing, and the OIDC claim and redirect rules. Run it with <code>go test ./...</code>.</li><li>Tests run automatically on every push and pull request via GitHub Actions, with race detection, vet, and formatting checks.</li></ul><h3 id="upgrade-notes" tabindex="-1">Upgrade notes <a class="header-anchor" href="#upgrade-notes" aria-label="Permalink to &quot;Upgrade notes&quot;">​</a></h3><ul><li><p><strong>Everyone is signed out once.</strong> Session and trusted-device tokens are now hashed, so tokens issued before the upgrade no longer match. Sign in again.</p></li><li><p><strong>Cross-domain ForwardAuth needs configuration.</strong> If a protected app is on a different domain than <code>COOKIE_DOMAIN</code>, sign-in returns the user to the GateKeeper home page instead of the app until that domain is allowed. v0.9.3 adds a <strong>Protected app domains</strong> field in Settings for this; on v0.9.2 it is set with the <code>REDIRECT_ALLOWED_HOSTS</code> environment variable.</p></li><li><p><strong>Users on very old TOTP enrollments must re-enroll.</strong> Only affects secrets created before v0.4.0. They sign in with an email code and set up their authenticator again.</p></li></ul><hr><h2 id="v0-9-1" tabindex="-1">v0.9.1 <a class="header-anchor" href="#v0-9-1" aria-label="Permalink to &quot;v0.9.1&quot;">​</a></h2><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li><strong>Documentation build dependency</strong> - Bumped <code>vite</code> to <code>6.4.3</code> to resolve two advisories flagged by Dependabot: a <code>server.fs.deny</code> bypass on Windows alternate paths (high) and an NTLMv2 hash disclosure via <code>launch-editor</code> on Windows (medium). This only affects the documentation site&#39;s build tooling, not the GateKeeper server.</li></ul><h3 id="forwardauth-debugging" tabindex="-1">ForwardAuth debugging <a class="header-anchor" href="#forwardauth-debugging" aria-label="Permalink to &quot;ForwardAuth debugging&quot;">​</a></h3><ul><li><strong>Debug logging</strong> - Set <code>LOG_LEVEL=debug</code> to log the <code>X-Forwarded-Host</code>, proto, and URI each ForwardAuth verify receives, plus the target each login redirect resolves to. This pinpoints reverse-proxy header issues, such as a middleware <code>address</code> routed through the auth domain that rewrites <code>X-Forwarded-Host</code>. See <a href="/integrations/traefik-forwardauth.html#troubleshooting-login-redirects-back-to-the-auth-domain">Traefik ForwardAuth - Troubleshooting</a>.</li></ul><hr><h2 id="v0-9-0" tabindex="-1">v0.9.0 <a class="header-anchor" href="#v0-9-0" aria-label="Permalink to &quot;v0.9.0&quot;">​</a></h2><h3 id="split-public-and-admin-ports" tabindex="-1">Split public and admin ports <a class="header-anchor" href="#split-public-and-admin-ports" aria-label="Permalink to &quot;Split public and admin ports&quot;">​</a></h3><p>The admin panel now runs on a dedicated port (<code>ADMIN_PORT</code>, default <code>8283</code>) separate from the public login and OIDC endpoints (<code>PORT</code>, default <code>8282</code>). Point your reverse proxy at port <code>8283</code> for the admin panel and restrict that route to your private network. The public port handles login, OIDC, ForwardAuth, and user-facing pages.</p><p>The admin panel is now served at the root of its port, so you can give it its own domain (e.g. <code>admin.auth.example.com</code>) with no <code>/admin</code> path prefix. Set <code>ADMIN_URL</code> to that domain so admin passkeys work. To keep a path prefix, set <code>ADMIN_BASE_PATH=/admin</code>.</p><h3 id="admin-passkeys-on-a-subdomain" tabindex="-1">Admin passkeys on a subdomain <a class="header-anchor" href="#admin-passkeys-on-a-subdomain" aria-label="Permalink to &quot;Admin passkeys on a subdomain&quot;">​</a></h3><p>The admin panel can use passkeys when it runs on its own subdomain (e.g. <code>admin.auth.example.com</code>). Set <code>ADMIN_URL</code> and GateKeeper adds that origin to the WebAuthn allowed origins so registration and login work. The admin subdomain must sit under the same registrable domain as <code>BASE_URL</code>. See <a href="/auth/passkeys.html#admin-on-a-subdomain">Passkeys - Admin on a subdomain</a>.</p><h3 id="backup-restore-and-upload" tabindex="-1">Backup restore and upload <a class="header-anchor" href="#backup-restore-and-upload" aria-label="Permalink to &quot;Backup restore and upload&quot;">​</a></h3><ul><li><strong>One-step restore</strong> - Restoring a backup now completes automatically on the next restart. GateKeeper detects the staged database on startup, swaps it in, and clears stale write-ahead-log files. The old flow that required manually renaming files inside the container is gone.</li><li><strong>Upload a backup</strong> - A new <strong>Upload backup</strong> button on the Backups page restores from a backup file you downloaded earlier, even if it is no longer in storage. The file is decrypted with your <code>SECRET_KEY</code> and validated before staging. See <a href="/admin/backups.html#restoring-a-backup">Backups - Restoring a backup</a>.</li></ul><h3 id="bug-fixes-2" tabindex="-1">Bug fixes <a class="header-anchor" href="#bug-fixes-2" aria-label="Permalink to &quot;Bug fixes&quot;">​</a></h3><ul><li><strong>QR sign-in into proxied apps</strong> - Signing in with a QR code now correctly returns you to a ForwardAuth-protected app on another domain. The QR flow now performs the same cross-domain session handoff as password login, instead of dropping you on your profile page.</li><li><strong>Admin panel icons and avatars</strong> - OIDC client icons and user avatars now load on the admin panel when it runs on its own port or domain. Their routes were previously only registered on the public port.</li></ul><hr><h2 id="v0-8-0" tabindex="-1">v0.8.0 <a class="header-anchor" href="#v0-8-0" aria-label="Permalink to &quot;v0.8.0&quot;">​</a></h2><h3 id="qr-code-sign-in" tabindex="-1">QR code sign-in <a class="header-anchor" href="#qr-code-sign-in" aria-label="Permalink to &quot;QR code sign-in&quot;">​</a></h3><ul><li><strong>Scan to sign in</strong> - A new QR code tab on the login page lets you sign in to any device by scanning a code with your phone. Approve the login on your phone and the PC session is created automatically. No password or email code needed on the secondary device. See <a href="/auth/qr-login.html">QR code sign-in</a>.</li><li><strong>One-time tokens</strong> - Each QR code encodes a short-lived token (5 minute TTL) that is deleted from the database once used or expired. Expired codes reload automatically after a short pause.</li></ul><h3 id="credential-injection" tabindex="-1">Credential injection <a class="header-anchor" href="#credential-injection" aria-label="Permalink to &quot;Credential injection&quot;">​</a></h3><ul><li><strong>Per-policy auto-login</strong> - Store a username and password on any access policy. When <code>/auth/verify</code> approves a request, GateKeeper returns an <code>Authorization: Basic</code> header that your reverse proxy forwards to the upstream app. The app receives a pre-authenticated request and skips its own login prompt - the same pattern as Authentik&#39;s outpost proxy. See <a href="/admin/policies.html#credential-injection">Access policies - Credential injection</a>.</li><li><strong>Encrypted storage</strong> - Injected passwords are encrypted with AES-256-GCM using a key derived from <code>SECRET_KEY</code> before being written to the database.</li><li><strong>Traefik, Nginx, and Caddy support</strong> - The integrations page documents how to configure each reverse proxy to forward the injected <code>Authorization</code> header.</li></ul><h3 id="admin-api-key" tabindex="-1">Admin API key <a class="header-anchor" href="#admin-api-key" aria-label="Permalink to &quot;Admin API key&quot;">​</a></h3><ul><li><strong>Personal API key</strong> - Each admin account can generate a personal API key from the My Account page. Send it as <code>X-Api-Key</code> to authenticate server-side API requests without a browser session. Useful for dashboards and monitoring scripts. See <a href="/admin/api-key.html">Admin API key</a>.</li><li><strong>Rotate on demand</strong> - Keys can be rotated at any time from the profile page. The old key is invalidated immediately.</li></ul><h3 id="bug-fixes-3" tabindex="-1">Bug fixes <a class="header-anchor" href="#bug-fixes-3" aria-label="Permalink to &quot;Bug fixes&quot;">​</a></h3><ul><li><strong>Passkey OIDC redirect</strong> - Logging in with a passkey during an OIDC flow now correctly redirects back to the app after authentication. Previously the <code>oidc_request</code> token was lost during the passkey finish step, leaving the user on their profile page instead.</li></ul><hr><h2 id="v0-7-0" tabindex="-1">v0.7.0 <a class="header-anchor" href="#v0-7-0" aria-label="Permalink to &quot;v0.7.0&quot;">​</a></h2><h3 id="backup-and-restore" tabindex="-1">Backup and restore <a class="header-anchor" href="#backup-and-restore" aria-label="Permalink to &quot;Backup and restore&quot;">​</a></h3><ul><li><strong>Encrypted backups</strong> - Snapshot the database on demand or automatically (hourly, daily, or weekly). Each backup is encrypted with AES-256-GCM using a key derived from <code>SECRET_KEY</code>. See <a href="/admin/backups.html">Backups</a>.</li><li><strong>Local storage</strong> - Write backups to a directory inside the container. Mount a host volume to persist them across restarts.</li><li><strong>S3-compatible storage</strong> - Upload backups to any S3-compatible object store: AWS S3, Cloudflare R2, Backblaze B2, MinIO, Garage, and others. No SDK dependency - uses a minimal AWS Signature v4 implementation.</li><li><strong>Retention policy</strong> - Keep the last N backups. Older ones are deleted from storage automatically when a new backup is created.</li><li><strong>Download and restore</strong> - Download any backup from the Backups page or trigger an in-place restore. The restore decrypts the backup and writes a <code>.restore</code> file; a restart completes the swap.</li></ul><h3 id="password-policy" tabindex="-1">Password policy <a class="header-anchor" href="#password-policy" aria-label="Permalink to &quot;Password policy&quot;">​</a></h3><ul><li><strong>Configurable password rules</strong> - Set a minimum password length (8-72) and require uppercase letters, numbers, or symbols from Settings. Rules apply at registration, password change, and password reset. Defaults to 8-character minimum with no complexity requirements.</li></ul><h3 id="oidc-improvements" tabindex="-1">OIDC improvements <a class="header-anchor" href="#oidc-improvements" aria-label="Permalink to &quot;OIDC improvements&quot;">​</a></h3><ul><li><strong>Client test button</strong> - Test any OIDC client directly from the Clients page. Shows a checklist of config details and opens a live auth flow with <code>prompt=login</code> so you can verify the full round-trip without wiring up the app.</li><li><strong>Groups claim in userinfo</strong> - The <code>groups</code> array is now included in the <code>/userinfo</code> endpoint response in addition to the ID token. Apps like Grafana that call <code>/userinfo</code> after the token exchange now receive group membership correctly.</li></ul><h3 id="audit-log" tabindex="-1">Audit log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit log&quot;">​</a></h3><ul><li><strong>Server-side event filter</strong> - Filter the audit log by event category (Login, User, Admin, Invites) via URL params. Filters persist across page loads and are applied server-side, removing the 1000-row client-side cap.</li><li><strong>CSV export</strong> - Export the full filtered result set as a CSV file with no row limit. The export respects the active day range and event category filter.</li></ul><h3 id="bug-fixes-4" tabindex="-1">Bug fixes <a class="header-anchor" href="#bug-fixes-4" aria-label="Permalink to &quot;Bug fixes&quot;">​</a></h3><ul><li><strong>Dashboard sign-in activity</strong> - Social logins (<code>login.social</code>) and admin logins (<code>admin.login</code>, <code>admin.login.passkey</code>) are now counted in the sign-in stats and activity chart on the dashboard.</li></ul><hr><h2 id="v0-6-0" tabindex="-1">v0.6.0 <a class="header-anchor" href="#v0-6-0" aria-label="Permalink to &quot;v0.6.0&quot;">​</a></h2><h3 id="multiple-admin-accounts" tabindex="-1">Multiple admin accounts <a class="header-anchor" href="#multiple-admin-accounts" aria-label="Permalink to &quot;Multiple admin accounts&quot;">​</a></h3><ul><li><strong>Admin accounts</strong> - Create and manage multiple admin accounts from the new Admins page. Each admin has a display name, email, and password. The currently signed-in admin is shown with a &quot;you&quot; indicator. Deleting your own account or the last remaining account is blocked.</li><li><strong>Promote user to admin</strong> - Any regular user can be promoted to an admin account directly from their user detail page. Sets a separate admin password and creates an independent admin account using the user&#39;s email and display name.</li><li><strong>Admin profile redesign</strong> - The My Account page is redesigned to match the user detail layout. Includes display name editing, active session count, and a &quot;Revoke all other sessions&quot; action.</li></ul><h3 id="login-page-branding" tabindex="-1">Login page branding <a class="header-anchor" href="#login-page-branding" aria-label="Permalink to &quot;Login page branding&quot;">​</a></h3><ul><li><strong>Login page branding</strong> - Set an app name, tagline, and logo URL from Settings. The app name replaces &quot;GateKeeper&quot; in the sign-in heading. The tagline appears below the heading. The logo replaces the GateKeeper mark on the login, registration, and password reset pages. OIDC client icons still take priority over the logo when signing in via a specific client.</li></ul><h3 id="email-branding" tabindex="-1">Email branding <a class="header-anchor" href="#email-branding" aria-label="Permalink to &quot;Email branding&quot;">​</a></h3><ul><li><strong>Email templates</strong> - All outgoing emails (login codes, password resets, password change notifications) now use a clean branded layout. Set a sender name, logo URL, and accent color from Settings. The header background and CTA button color both use the accent color. Defaults to &quot;GateKeeper&quot; as the sender name and blue (<code>#2563eb</code>) as the accent.</li></ul><h3 id="reverse-proxy-integrations" tabindex="-1">Reverse proxy integrations <a class="header-anchor" href="#reverse-proxy-integrations" aria-label="Permalink to &quot;Reverse proxy integrations&quot;">​</a></h3><ul><li><strong>Nginx auth_request</strong> - Full configuration guide for protecting sites with nginx&#39;s <code>auth_request</code> module. See <a href="/integrations/nginx.html">Nginx auth_request</a>.</li><li><strong>Caddy forward_auth</strong> - Full Caddyfile guide for protecting sites with Caddy&#39;s <code>forward_auth</code> directive. See <a href="/integrations/caddy.html">Caddy forward_auth</a>.</li><li><strong>X-Auth-Groups header</strong> - The <code>/auth/verify</code> endpoint now returns an <code>X-Auth-Groups</code> header containing a comma-separated list of the authenticated user&#39;s group names. All three reverse proxy integrations (Traefik, Nginx, Caddy) forward this header to the upstream application.</li></ul><hr><h2 id="v0-5-0" tabindex="-1">v0.5.0 <a class="header-anchor" href="#v0-5-0" aria-label="Permalink to &quot;v0.5.0&quot;">​</a></h2><h3 id="social-login" tabindex="-1">Social login <a class="header-anchor" href="#social-login" aria-label="Permalink to &quot;Social login&quot;">​</a></h3><ul><li><strong>Social login</strong> - Sign in with GitHub, Google, or Discord. Enable each provider from Settings with an OAuth2 client ID and secret. A &quot;Continue with...&quot; button appears on the login page for each enabled provider. On first sign-in, GateKeeper auto-links the provider to an existing account if the email matches. Users can connect and disconnect providers from their profile page. See <a href="/admin/social-login.html">Social login</a>.</li></ul><h3 id="groups" tabindex="-1">Groups <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;Groups&quot;">​</a></h3><ul><li><strong>Groups</strong> - Create named groups and assign users to them. Group membership is automatically included as a <code>groups</code> claim in all OIDC tokens, enabling role mapping in apps like Grafana and Jellyfin without any scope configuration. Manage group members from the Groups page or directly from a user&#39;s profile page. See <a href="/admin/groups.html">Groups</a> for Grafana and Jellyfin config examples.</li></ul><h3 id="user-self-registration" tabindex="-1">User self-registration <a class="header-anchor" href="#user-self-registration" aria-label="Permalink to &quot;User self-registration&quot;">​</a></h3><ul><li><strong>Registration modes</strong> - Choose between disabled, invite-only, open, and approval-required modes from Settings. In open mode anyone can create an account immediately. In approval mode accounts are held in a pending queue until an admin approves or rejects them from the Users page. A &quot;Create account&quot; link appears on the sign-in page when registration is open or approval-mode. Domain restrictions can limit which email domains are allowed to self-register. See <a href="/admin/registration.html">Registration</a>.</li></ul><h3 id="invite-links" tabindex="-1">Invite links <a class="header-anchor" href="#invite-links" aria-label="Permalink to &quot;Invite links&quot;">​</a></h3><ul><li><strong>Invite links</strong> - Generate single-use registration links from the Invites page. Each link can be tied to a specific email address (pre-filling and locking the registration form) or left open for any address. Links expire after 1, 3, 7, 14, or 30 days. The raw token is shown once at creation time; only a SHA-256 hash is stored. See <a href="/admin/invites.html">Invites</a>.</li></ul><h3 id="oidc-improvements-1" tabindex="-1">OIDC improvements <a class="header-anchor" href="#oidc-improvements-1" aria-label="Permalink to &quot;OIDC improvements&quot;">​</a></h3><ul><li><strong>RP-initiated logout</strong> - Signing out of an OIDC client (e.g., Grafana) now also clears the GateKeeper session cookie. The <code>post_logout_redirect_uri</code> parameter is honoured so users land back on the correct page.</li><li><strong>Token introspection</strong> - The <code>/oauth/introspect</code> endpoint (RFC 7662) is supported. APIs and services can verify bearer tokens server-side by calling the endpoint with their client credentials. See <a href="/admin/managing-clients.html">Managing clients</a>.</li><li><strong>Client credentials flow</strong> - Enable machine-to-machine auth per client by setting a list of allowed scopes on the client.</li><li><strong>Custom claims</strong> - Inject extra fields into tokens on a per-client basis. Map user ID, email, display name, group membership, or a literal string to any claim key. Manage from the claims icon on the OIDC Clients page. See <a href="/admin/custom-claims.html">Custom claims</a>. Services call <code>POST /oauth/token</code> with <code>grant_type=client_credentials</code> and receive an access token with <code>sub</code> set to the client ID. See <a href="/admin/managing-clients.html">Managing clients</a>.</li></ul><h3 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h3><ul><li><strong>Live stats</strong> - The sign-ins, failed attempts, and OIDC token counts on the dashboard now refresh every 30 seconds without a full page reload.</li></ul><hr><h2 id="v0-4-0" tabindex="-1">v0.4.0 <a class="header-anchor" href="#v0-4-0" aria-label="Permalink to &quot;v0.4.0&quot;">​</a></h2><h3 id="security-hardening" tabindex="-1">Security hardening <a class="header-anchor" href="#security-hardening" aria-label="Permalink to &quot;Security hardening&quot;">​</a></h3><ul><li><strong>AES-256-GCM for TOTP secrets</strong> - TOTP secrets are now encrypted with AES-256-GCM before storage. The encryption key is derived from <code>SECRET_KEY</code> using SHA-256. Existing secrets encrypted with the older XOR scheme are migrated automatically on next login - no action required.</li><li><strong>HMAC-SHA256 for OTP codes</strong> - Email OTP codes are no longer stored as plaintext. They are stored as HMAC-SHA256 digests keyed with <code>SECRET_KEY</code>. A database dump without the key cannot reconstruct active codes.</li><li><strong>CSRF protection on all user endpoints</strong> - All authenticated state-changing POST requests (password change, 2FA enrollment, session revocation, passkey deletion, name and avatar update) now validate a CSRF token. Previously only the admin panel validated CSRF.</li><li><strong>Login rate limiting</strong> - The login endpoint now enforces an IP-based rate limit of 20 failed attempts per 15-minute window. Excess attempts receive an error before any password check.</li><li><strong>OTP issuance rate limit</strong> - Each user can request at most 3 OTP codes per 10-minute window, preventing email flooding.</li><li><strong>Tightened Content-Security-Policy</strong> - Added <code>object-src &#39;none&#39;</code>, <code>base-uri &#39;self&#39;</code>, <code>connect-src &#39;self&#39;</code>, and <code>frame-ancestors &#39;none&#39;</code>. Added <code>https://www.gravatar.com</code> to <code>img-src</code>.</li></ul><h3 id="user-home-redesign" tabindex="-1">User home redesign <a class="header-anchor" href="#user-home-redesign" aria-label="Permalink to &quot;User home redesign&quot;">​</a></h3><ul><li><strong>New user home layout</strong> - The authenticated home page (<code>/</code>) is fully redesigned. It shows a header with the GateKeeper logo, email, and theme toggle; a page head with avatar, display name, and inline name edit; three stat cards (sign-in methods, passkeys, sessions); a sign-in methods card; a passkeys card; and an active sessions card.</li><li><strong>Session management</strong> - Users can view all active sessions (device, browser, IP, last seen, time ago) and revoke individual sessions or all sessions except the current one directly from the home page.</li></ul><h2 id="v0-3-0" tabindex="-1">v0.3.0 <a class="header-anchor" href="#v0-3-0" aria-label="Permalink to &quot;v0.3.0&quot;">​</a></h2><ul><li><strong>Webhooks</strong> - Send push notifications to Discord, Slack, Telegram, ntfy (public and self-hosted), generic JSON endpoints, or email when auth and admin events occur. Configure per-webhook event subscriptions and test delivery inline from the Webhooks page.</li><li><strong>Access policies</strong> - Create named policies and assign users to them. Attach a policy to an OIDC client to restrict which users can complete authorization, or reference it via <code>?policy=&lt;name&gt;</code> on <code>/auth/verify</code> for ForwardAuth routes. Policy ForwardAuth URL shown with copy button on the policies page.</li><li><strong>Admin audit logging</strong> - Admin sign-in (password and passkey), sign-out, failed login attempts, and user deletion are now recorded in the audit log alongside all other events.</li><li><strong>Audit log retention</strong> - Set a retention period in Settings. Events older than the configured number of days are deleted automatically on startup and daily. Default is 90 days; set to 0 to keep all events.</li><li><strong>Audit log date filter</strong> - Filter by Today, 7 days, 30 days, 90 days, or All time directly from the toolbar.</li><li><strong>User profile</strong> - Users can set a display name and pull in a Gravatar avatar from their home screen. The image is fetched server-side and cached in the database so the browser never contacts Gravatar directly.</li><li><strong>Avatars everywhere</strong> - Display name and avatar appear in the admin user list, user detail page, audit log rows, and dashboard recent events.</li><li><strong>Dashboard redesign</strong> - Real sparklines from the database on the sign-ins, failed attempts, and OIDC traffic cards. New cards for active sessions, 2FA adoption, and audit log stats. Auth methods card with 24h / 7d / 30d range toggle.</li><li><strong>Command palette fixes</strong> - <code>⌘K</code> / <code>Ctrl+K</code> palette now has working keyboard navigation (arrow keys, Enter). All pages including Policies, Webhooks, and Integrations appear in the navigate list. Searching users matches display name in addition to email.</li><li><strong>New user modal</strong> - Creating a user from the Users page now opens an inline modal instead of navigating to a separate page.</li><li><strong>Policies table</strong> - Policies page redesigned to match the OIDC clients table layout with description, member count, and used-by columns.</li><li><strong>System health section</strong> - Consolidates configuration warnings (locked accounts, users without 2FA, OIDC signing key status).</li></ul><h2 id="v0-2-0" tabindex="-1">v0.2.0 <a class="header-anchor" href="#v0-2-0" aria-label="Permalink to &quot;v0.2.0&quot;">​</a></h2><ul><li><strong>OIDC provider</strong> - Full authorization code + PKCE flow. Apps can now use GateKeeper as a proper OIDC identity provider (Traefik Manager, Termix, Grafana, Jellyfin, etc.)</li><li><strong>OIDC client icons</strong> - Add an icon URL per client. Icons are fetched and cached server-side at save time; the login page loads them from GateKeeper, not external servers.</li><li><strong>Login page branding</strong> - When signing in via OIDC, the login page shows the app name and cached icon instead of the GateKeeper logo.</li><li><strong>Client editing</strong> - Edit name, icon, redirect URIs, and optionally rotate the secret of any OIDC client without deleting and recreating it.</li><li><strong>OIDC endpoint reference</strong> - The clients page now shows all endpoint URLs (authorization, token, userinfo, JWKS, discovery) with copy buttons.</li><li><strong>Secret generator</strong> - One-click cryptographically random secret generation in the new/edit client dialogs.</li><li><strong>Trusted device tokens</strong> - After passing 2FA, a 30-day <code>gk_trust</code> cookie is set. Users on trusted devices skip the second factor until it expires.</li><li><strong>Cross-domain ForwardAuth</strong> - HMAC-signed short-lived tokens allow GateKeeper to set per-host cookies for apps on different TLDs.</li><li><strong>Interactive dashboard chart</strong> - Sign-in activity chart with 24h / 7d / 30d range toggle and hover tooltips backed by real data.</li><li><strong>Real auth method breakdown</strong> - Dashboard shows live percentages for passkey, TOTP, email OTP, and OIDC logins in the last 24 hours.</li><li><strong>Command palette</strong> - <code>⌘K</code> / <code>Ctrl+K</code> opens a search palette. Type to search users and clients by name. Keyboard shortcuts <code>g d/u/c/a/s</code> navigate between sections.</li><li><strong>Audit log improvements</strong> - Event type filter chips (auth / admin / oidc), kind filter (success / warn / fail / info), per-row filter button, correct event count.</li><li><strong>Mobile navigation</strong> - Bottom navigation bar on screens under 760px.</li><li><strong>Admin sidebar</strong> - Live user and client counts, version number in the footer.</li><li><strong>New user sign-in methods</strong> - Create users as &quot;Email + Password&quot; or &quot;Email Only&quot; (passwordless) directly from the new user form.</li><li><strong>OIDC post-login redirect</strong> - After authenticating via OIDC, GateKeeper correctly completes the auth request and redirects back to the app with an authorization code.</li><li><strong>Theme persistence</strong> - Dark/light/auto preference now survives full page navigation (was blocked by CSP preventing the inline bootstrap script).</li></ul><h2 id="v0-1-0" tabindex="-1">v0.1.0 <a class="header-anchor" href="#v0-1-0" aria-label="Permalink to &quot;v0.1.0&quot;">​</a></h2><p>Initial release.</p><ul><li>Password + email OTP login</li><li>Passwordless email OTP mode (per-user, admin-configurable)</li><li>TOTP enrollment with QR code and recovery codes</li><li>Passkey (WebAuthn) registration and authentication</li><li>Password recovery via email with rate-limited, single-use tokens</li><li>Authenticated password change with session invalidation</li><li>Forced password change on admin-created accounts</li><li>Traefik ForwardAuth middleware (<code>/auth/verify</code>)</li><li>OIDC provider with authorization code + PKCE flow</li><li>OIDC scopes: <code>openid</code>, <code>email</code>, <code>profile</code>, <code>offline_access</code></li><li>RS256 signing with 30-day key rotation</li><li>First-run setup page at <code>/admin/setup</code> - no env vars needed for admin credentials</li><li>Admin UI for user and OIDC client management</li><li>Admin profile page - change password, enroll TOTP, register passkeys</li><li>All runtime settings (SMTP, session TTL, allowed domains) configurable in the admin UI</li><li>Append-only audit log</li><li>SQLite persistence with embedded migrations</li><li>Docker multi-stage build (golang:1.26-alpine)</li><li>Astro Starlight documentation site</li></ul>',113)])])}const p=a(n,[["render",r]]);export{g as __pageData,p as default};
